    let authoritativeState = state
    let reactionEvents: Dnd5eCombatEvent[] = []
    let authoritativeAction = await applyTeleportWard(action)
    const withReactionEvents = <T extends import('../application/combat/dnd5eCombatRules').Dnd5eActionResult>(result: T): T =>
      reactionEvents.length > 0
        ? { ...result, events: [...reactionEvents, ...result.events] } as T
        : result
