      'divine-favor': '神恩',
      'divine-strike': '神圣打击', 'weapon-damage-rider': '特性附伤', 'lifedrinker': '饮命者', 'foe-slayer': '屠灭众敌',
      'persistent-area-rider': '区域附伤',
