  const handleSharedShieldSpellChoice = async (useShieldSpell: boolean) => {
    if (!sharedShieldSpellPrompt || !activeMap) return
    const prompt = sharedShieldSpellPrompt
    suppressedShieldSpellPromptIdsRef.current.add(prompt.id)
    setSharedShieldSpellPrompt(null)
    const response = { useShieldSpell }
    await answerSharedCombatInterrupt(prompt.id, response)
    const pending = pendingSharedShieldSpellRef.current
    if (pending?.id === prompt.id) {
      await finishSharedCombatInterrupt(prompt.id, response)
      if (pendingSharedShieldSpellRef.current?.id === prompt.id) {
        pendingSharedShieldSpellRef.current = null
        pending.resolve(useShieldSpell)
      }
    }
  }

  const handleSharedCounterspellChoice = async (useCounterspell: boolean, slotLevel?: number) => {
    if (!sharedCounterspellPrompt || !activeMap) return
    const prompt = sharedCounterspellPrompt
    suppressedCounterspellPromptIdsRef.current.add(prompt.id)
    setSharedCounterspellPrompt(null)
    const allowedSlotLevels = prompt.counterspellSlotLevels.length > 0
      ? prompt.counterspellSlotLevels
      : [prompt.counterspellSlotLevel]
    const counterspellSlotLevel = slotLevel != null && allowedSlotLevels.includes(slotLevel)
      ? slotLevel
      : allowedSlotLevels[0]
    await answerSharedCombatInterrupt(prompt.id, {
      useCounterspell,
      ...(useCounterspell && counterspellSlotLevel != null ? { counterspellSlotLevel } : {}),
    })
  }

